<script>
(function(){const openModal=(id)=>{const el=document.getElementById(id);if(el){el.classList.add('open');document.body.style.overflow='hidden';}};const closeModal=(el)=>{const modal=el?.classList?.contains('modal')?el:el?.closest?.('.modal');if(modal){modal.classList.remove('open');if(!document.querySelector('.modal.open'))document.body.style.overflow='';}};window.openModal=openModal;window.closeModal=closeModal;document.addEventListener('click',(e)=>{const opener=e.target.closest('[data-open-modal]');if(opener){e.preventDefault();const current=opener.closest('.modal');if(opener.hasAttribute('data-close-modal')&&current)closeModal(current);openModal(opener.dataset.openModal);return;}const closer=e.target.closest('[data-close-modal]');if(closer){e.preventDefault();closeModal(closer);return;}if(e.target.classList.contains('modal'))closeModal(e.target);const tab=e.target.closest('[data-tab-target]');if(tab){const group=tab.closest('[data-tabs]')||document;group.querySelectorAll('[data-tab-target]').forEach(x=>x.classList.remove('active'));group.querySelectorAll('.tab-panel').forEach(x=>x.classList.remove('active'));tab.classList.add('active');const panel=document.getElementById(tab.dataset.tabTarget);if(panel)panel.classList.add('active');if(history.replaceState)history.replaceState(null,'','#'+tab.dataset.tabTarget);}});document.addEventListener('keydown',(e)=>{if(e.key==='Escape'){const modal=document.querySelector('.modal.open');if(modal)closeModal(modal);}});document.querySelectorAll('[data-tabs]').forEach(group=>{const hash=location.hash.replace('#','');if(hash){const tab=group.querySelector(`[data-tab-target="${CSS.escape(hash)}"]`);if(tab)tab.click();}});setTimeout(()=>document.querySelectorAll('[data-auto-dismiss]').forEach((el)=>{el.style.transition='opacity .35s';el.style.opacity='0';setTimeout(()=>el.remove(),350);}),5000);document.querySelectorAll('.modal input:not([placeholder]),.modal textarea:not([placeholder])').forEach((el)=>{const l=el.closest('label');if(l){const t=(l.childNodes[0]?.textContent||'').trim();if(t)el.setAttribute('placeholder','Enter '+t.toLowerCase());}});const side=document.querySelector('.side');document.getElementById('menuToggle')?.addEventListener('click',()=>side?.classList.toggle('open'));document.querySelectorAll('.side a').forEach(a=>{try{const current=location.pathname.replace(/\/$/,'');const href=new URL(a.href).pathname.replace(/\/$/,'');if(href&&current===href)a.classList.add('active');}catch(_){}a.addEventListener('click',()=>{if(window.innerWidth<=800)side?.classList.remove('open');});});})();
</script>
